import {calculatePlateCosts,costForMenu} from './domain.mjs';
import {esc,tr,money,itemName} from './views.mjs';
export function intelligenceView({state,language:l,demo}) {
 const report=calculatePlateCosts(state),selected=state.menu[0],recipe=costForMenu(state,selected.id),row=report.rows.find(r=>r.menuId===selected.id),cost=recipe.costCents,first=recipe.ingredients?.[0];
 return `<div class="cp-shell cp-view"><section class="cp-hero"><div class="cp-hero-copy" data-reveal><p class="cp-eyebrow">${esc(state.settings.name)} / ${tr(l,'COST INTELLIGENCE','เข้าใจต้นทุน')}</p><h1>${tr(l,'Know<br>every plate.','รู้ต้นทุน<br>ทุกจาน')}</h1><p class="cp-subtitle">${tr(l,'From the receipt to the recipe. From each order to its margin.','จากใบซื้อสู่สูตรอาหาร จากทุกออเดอร์สู่กำไรส่วนเกิน')}</p><div class="cp-hero-actions"><button class="cp-button" data-action="receipt">${tr(l,'Read a receipt','อ่านใบซื้อ')} ↗</button><button class="cp-button secondary" data-recipe="${selected.id}">${tr(l,'Map a recipe','กำหนดสูตรต่อจาน')}</button></div><div class="cp-hero-actions cp-discovery"><a class="cp-link" href="#order">${tr(l,'Open order menu','เปิดเมนูสั่งอาหาร')} →</a><a class="cp-link" href="${demo?'#ai':'/copilot/demo#ai'}">${tr(l,'Explore AI demo','ลองเดโม AI')} →</a></div><p class="cp-note">${demo?tr(l,'Sample costs and orders · illustrative 30% online fee.','ต้นทุนและออเดอร์ตัวอย่าง · ค่าธรรมเนียมออนไลน์สมมติ 30%'):tr(l,'Purchase evidence + merchant-defined portions.','หลักฐานการซื้อ + ปริมาณต่อจานที่ร้านกำหนด')}</p></div><div class="cp-scene" data-reveal><button class="cp-window" data-scene-light aria-pressed="false" aria-label="${tr(l,'Change mountain lighting','เปลี่ยนแสงภูเขา')}"><span class="cp-camera"><img class="cp-landscape" src="/images/studio-window.webp" alt="" width="1200" height="800" fetchpriority="high"><span class="cp-reflection"></span><span class="cp-light"></span></span></button><div class="cp-float-ticket cp-cost-focus"><span class="cp-eyebrow">${esc(itemName(selected,l))}</span><strong>${cost==null?'—':money(cost,l)}</strong><span>${tr(l,'variable cost / plate','ต้นทุนผันแปร / จาน')}</span><span class="cp-ticket-stroke"></span><small>${tr(l,'Store price','ราคาหน้าร้าน')} <b>${money(selected.storePriceCents,l)}</b></small></div><span class="cp-scene-caption">${tr(l,'The details make the difference.','เห็นคุณค่าในทุกรายละเอียด')}</span></div></section><section data-reveal><div class="cp-service-title"><div><p class="cp-eyebrow">${tr(l,'FOLLOW THE COST','ตามเส้นทางต้นทุน')}</p><h2>${tr(l,'One connected picture.','เห็นภาพเดียวกัน')}</h2></div><button class="cp-link" data-recipe="${selected.id}">${tr(l,'Inspect the recipe','ดูสูตรคำนวณ')} ↗</button></div><div class="cp-cost-flow"><div class="cp-cost-stage"><span class="cp-eyebrow">01 / ${first?.source==='receipt'?tr(l,'RECEIPT','ใบซื้อ'):first?.source==='demo'?tr(l,'SAMPLE PURCHASE','ตัวอย่างการซื้อ'):tr(l,'PURCHASE COST','ต้นทุนซื้อ')}</span><h3>${first?esc(first.name):tr(l,'Purchase evidence','หลักฐานการซื้อ')}</h3><strong>${first?money(first.purchaseCostCents,l):'—'}</strong><small>${first?`${first.purchaseQuantity} ${esc(first.unit)} · ${tr(l,'purchased quantity','ปริมาณซื้อ')}`:tr(l,'Read and confirm a supplier receipt','อ่านและยืนยันใบซื้อวัตถุดิบ')}</small></div><span class="cp-flow-arrow" aria-hidden="true">→</span><div class="cp-cost-stage"><span class="cp-eyebrow">02 / ${tr(l,'RECIPE','สูตรต่อจาน')}</span><h3>${first?`${first.portionQuantity} ${esc(first.unit)} ${tr(l,'per plate','ต่อจาน')}`:tr(l,'Confirm the portion','ยืนยันปริมาณต่อจาน')}</h3><strong>${first?money(first.portionCostCents,l):'—'}</strong><small>${tr(l,'Ingredient cost for this portion','ต้นทุนวัตถุดิบสำหรับส่วนนี้')}</small></div><span class="cp-flow-arrow" aria-hidden="true">→</span><div class="cp-cost-stage"><span class="cp-eyebrow">03 / ${tr(l,'ORDER','ออเดอร์')}</span><h3>${esc(itemName(selected,l))}</h3><strong>${cost==null?'—':money(selected.storePriceCents-cost,l)}</strong><small>${tr(l,'In-store contribution / plate','กำไรส่วนเกินหน้าร้าน / จาน')}</small></div></div><p class="cp-note">${tr(l,'Contribution includes the full mapped recipe, packaging and entered variable costs. Fixed overhead, tax and unentered costs remain outside this estimate.','กำไรส่วนเกินรวมต้นทุนสูตร บรรจุภัณฑ์และต้นทุนผันแปรที่กรอก ยังไม่รวมค่าใช้จ่ายคงที่ ภาษี และต้นทุนที่ไม่ระบุ')}</p></section><section class="cp-source-section" data-reveal><div class="cp-service-title"><div><p class="cp-eyebrow">${tr(l,'ONE COST MODEL. MANY SOURCES.','ต้นทุนเดียว เชื่อมได้หลายแหล่ง')}</p><h2>${tr(l,'Meet your workflow.','เข้ากับวิธีทำงานของคุณ')}</h2></div><button class="cp-button secondary" data-action="import-csv">${tr(l,'Import order CSV','นำเข้า CSV ออเดอร์')}</button></div><div class="cp-source-switch">${demo?`<a class="cp-button secondary" href="#order">${tr(l,'QR order menu','เมนูสั่งผ่าน QR')} ↗</a>`+[['pos','Order records','ข้อมูลออเดอร์'],['delivery','Delivery feed','ข้อมูลเดลิเวอรี']].map(([id,en,th])=>`<button class="cp-button secondary" data-sample-source="${id}">${tr(l,en,th)} <small>${tr(l,'sample','ตัวอย่าง')}</small></button>`).join(''):`<a class="cp-button secondary" href="#order">${tr(l,'QR menu · native','เมนู QR · พร้อมใช้')}</a><button class="cp-button secondary" data-action="import-csv">${tr(l,'CSV adapter · available','ตัวเชื่อม CSV · พร้อมใช้')}</button><span class="cp-pill">${tr(l,'External APIs · not connected','API ภายนอก · ยังไม่เชื่อมต่อ')}</span>`}<a class="cp-link" href="#service">${tr(l,'See the shared queue','ดูคิวรวม')} ↗</a></div><p class="cp-note">${demo?tr(l,'Switchable sample adapters, one calculation engine. Live platform connectors still need their own integration.','สลับตัวเชื่อมจำลองได้ โดยใช้ระบบคำนวณเดียวกัน ตัวเชื่อมแพลตฟอร์มจริงยังต้องพัฒนาและเชื่อมต่อ'):tr(l,'Normalized SKU orders keep the calculation engine independent of your order or delivery system.','แปลงข้อมูลออเดอร์เป็นรูปแบบ SKU กลาง เพื่อแยกระบบคำนวณจากระบบออเดอร์และเดลิเวอรี')}</p></section><section class="cp-section" data-reveal><div class="cp-service-title"><div><p class="cp-eyebrow">${tr(l,'PLATE BY PLATE','เห็นต้นทุนทีละจาน')}</p><h2>${tr(l,'The margin view.','มองเห็นกำไรส่วนเกิน')}</h2></div><button class="cp-link" data-action="export-orders">${tr(l,'Export records','ส่งออกข้อมูล')} ↓</button></div><div class="cp-cost-ledger"><div class="cp-cost-row cp-menu-head"><span>SKU</span><span>${tr(l,'Items','จำนวน')}</span><span>${tr(l,'Order value','มูลค่า')}</span><span>${tr(l,'Variable cost + fees','ต้นทุนผันแปร + ค่าธรรมเนียม')}</span><span>${tr(l,'Contribution','กำไรส่วนเกิน')}</span></div>${report.rows.map(r=>`<div class="cp-cost-row"><div>${r.archived?`<span>${esc(itemName(r,l))} · ${tr(l,'archived','เก็บถาวร')}</span>`:`<button class="cp-link" data-recipe="${r.menuId}">${esc(itemName(r,l))} ↗</button>`}<small>${tr(l,'Store','หน้าร้าน')} ${r.channels.offline.quantity} / ${tr(l,'Online','ออนไลน์')} ${r.channels.online.quantity}</small></div><span data-label="${tr(l,'Items','จำนวน')}">${r.quantity}</span><span data-label="${tr(l,'Order value','มูลค่า')}">${money(r.orderValueCents,l)}</span><span data-label="${tr(l,'Variable cost','ต้นทุนผันแปร')}">${r.variableCostCents==null||r.feeCents==null?'—':money(r.variableCostCents+r.feeCents,l)}</span><strong data-label="${tr(l,'Contribution','กำไรส่วนเกิน')}">${r.contributionCents==null?'—':money(r.contributionCents,l)}</strong></div>`).join('')}</div><p class="cp-note">${tr(l,'Includes open and served orders; excludes cancellations. Current recipe costs are estimates, not historical net profit or confirmed payments. “—” means recipe costs or online fees are missing.','รวมออเดอร์ที่ยังไม่เสร็จและเสิร์ฟแล้ว ไม่รวมรายการยกเลิก ใช้ต้นทุนสูตรปัจจุบัน ไม่ใช่กำไรสุทธิย้อนหลังหรือยอดรับชำระ “—” หมายถึงขาดต้นทุนหรือค่าธรรมเนียม')}</p></section></div>`;
}
export function recipeForm({state,menuId,receipts=[],language:l}) {const menu=state.menu.find(m=>m.id===menuId),recipe=state.costings?.[menuId],ingredients=recipe?.ingredients?.length?recipe.ingredients:[{}];return `<form id="cp-recipe-form" data-menu="${menuId}" class="cp-form"><p>${esc(itemName(menu,l))} · ${tr(l,'Define usable purchase quantity and portion in the same unit.','กำหนดปริมาณซื้อที่ใช้ได้และปริมาณต่อจานเป็นหน่วยเดียวกัน')}</p><div id="cp-recipe-rows">${ingredients.map((i,n)=>ingredientFields(i,n,receipts,l)).join('')}</div><button type="button" class="cp-button secondary" data-action="add-ingredient">${tr(l,'Add ingredient','เพิ่มวัตถุดิบ')} +</button><div class="cp-form-pair"><label class="cp-field">${tr(l,'Packaging / plate (THB)','บรรจุภัณฑ์ / จาน (บาท)')}<input name="packaging" type="number" min="0" step=".01" required value="${(recipe?.packagingCents??0)/100}"></label><label class="cp-field">${tr(l,'Other variable cost / plate (THB)','ต้นทุนผันแปรอื่น / จาน (บาท)')}<input name="other" type="number" min="0" step=".01" required value="${(recipe?.otherVariableCents??0)/100}"></label></div><label class="cp-field">${tr(l,'Effective online fee (%) — leave blank if unknown','ค่าธรรมเนียมออนไลน์จริง (%) — เว้นว่างหากไม่ทราบ')}<input name="fee" type="number" min="0" max="99.99" step=".01" value="${recipe?.onlineFeeBps==null?'':recipe.onlineFeeBps/100}"></label><p class="cp-note">${recipe?.source==='demo'?tr(l,'Demo fee: 30% is illustrative, not a Grab rate. ','ค่าธรรมเนียมเดโม 30% เป็นตัวอย่าง ไม่ใช่อัตราของ Grab '):''}${tr(l,'Receipt OCR reads purchase amounts. The recipe and usable yield must be confirmed by the merchant.','OCR อ่านมูลค่าการซื้อ ร้านต้องยืนยันสูตรและปริมาณที่ใช้งานได้')}</p><button class="cp-button" type="submit">${tr(l,'Save recipe cost','บันทึกต้นทุนสูตร')}</button></form>`;}
export function ingredientFields(i,n,receipts,l) {const missing=i.receiptId&&!receipts.some(r=>r.id===i.receiptId&&r.items[i.receiptLine]?.lineTotal!=null);const unavailable=missing?`<option value="${esc(i.receiptId)}:${i.receiptLine}" selected>${tr(l,'Receipt unavailable — reconnect or explicitly choose manual','ไม่พบใบซื้อ — เชื่อมใหม่หรือเลือกกรอกเอง')}</option>`:'';const options=receipts.flatMap(r=>r.items.map((line,j)=>line.lineTotal==null?'':`<option value="${esc(r.id)}:${j}"${i.receiptId===r.id&&i.receiptLine===j?' selected':''}>${esc(r.name+' · '+line.name)}</option>`)).join('');return `<fieldset class="cp-ingredient" data-ingredient><legend>${tr(l,'Ingredient','วัตถุดิบ')} ${n+1}</legend><label class="cp-field">${tr(l,'Cost source','แหล่งต้นทุน')}<select name="source"><option value="manual">${tr(l,'Merchant entered / sample','ร้านกรอก / ตัวอย่าง')}</option>${unavailable}${options}</select></label><label class="cp-field">${tr(l,'Ingredient name','ชื่อวัตถุดิบ')}<input name="ingredientName" value="${esc(i.name||'')}" required maxlength="100"></label><div class="cp-form-pair"><label class="cp-field">${tr(l,'Purchase amount (THB)','มูลค่าซื้อ (บาท)')}<input name="purchaseCost" type="number" min=".01" step=".01" required value="${i.purchaseCostCents==null?'':i.purchaseCostCents/100}" ${i.receiptId?'readonly':''}></label><label class="cp-field">${tr(l,'Unit','หน่วย')}<select name="unit">${['g','ml','unit'].map(u=>`<option value="${u}" ${i.unit===u?'selected':''}>${u}</option>`).join('')}</select></label><label class="cp-field">${tr(l,'Usable quantity purchased','ปริมาณซื้อที่ใช้ได้')}<input name="purchaseQuantity" type="number" min=".001" step=".001" required value="${i.purchaseQuantity??''}"></label><label class="cp-field">${tr(l,'Quantity per plate / SKU','ปริมาณต่อจาน / SKU')}<input name="portionQuantity" type="number" min=".001" step=".001" required value="${i.portionQuantity??''}"></label></div><button type="button" class="cp-link" data-action="remove-ingredient">${tr(l,'Remove ingredient','ลบวัตถุดิบ')}</button></fieldset>`;}
